          "From the 8th to the 15th centuries AD, Muslim scholars made groundbreaking pioneer observations and wrote authoritative classical treatises that shaped global biology and medicine:",
          "1. Jabir Bin Hayyan (721–815 AD): Born in Iran, practiced in Iraq. Founder of experimental chemistry; authored foundational biological texts 'Al-Nabatat' (Treatise on Plants) and 'Al-Hayawan' (Treatise on Animals).",
          "2. Abdul Malik Asmai (740–828 AD): Born in Basra. Renowned zoologist who conducted detailed morphological and anatomical observations on domesticated animals. Authored 'Al-Kheil' (The Horse), 'Al-Ibil' (The Camel), 'Al-Sha' (The Sheep), 'Al-Wahoosh' (Wild Animals), and 'Khalaq-ul-Insan' (Human Anatomy and Physiology).",
          "3. Bu Ali Sina (Avicenna, 980–1037 AD): Born near Bukhara. A monumental polymath revered in the West as the 'Prince of Physicians'. His masterwork 'Al-Qanun fi al-Tibb' (The Canon of Medicine) served as the standard medical textbook in European universities for over five centuries.",
          "4. Abu-Usman Umar Al-Jahiz (776–868 AD): Authored the celebrated 7-volume encyclopedia 'Kitab al-Hayawan' (Book of Animals). Noted the seasonal migration of fish in the River Tigris and described the complex social communication and organization of ants.",
          "5. Al-Farabi (870–950 AD): Celebrated philosopher and biologist who wrote 'Kitab-ul-Nabatat' (Book on Plants) and 'Kitab-ul-Hayawanat' (Book on Animals).",
          "6. Abul Qasim Al-Zahrawi (Albucasis, 936–1004 AD): Eminent surgeon of Muslim Spain (Cordoba). Known as the father of modern surgery. Invented over 200 surgical instruments, pioneered lithotrity (bladder stone extraction), and wrote the 30-volume medical compendium 'Al-Tasrif'.",
          "7. Ibn-ul-Haitham (Alhazen, 965–1039 AD): Outstanding physicist and ophthalmologist. In his seminal work 'Kitab-ul-Manazir' (Book of Optics), he refuted the erroneous Greek intromission theory of vision and correctly identified the retina as the photoreceptive seat of sight.",
          "8. Ali Bin Isa (Jesu Haly, 10th Century AD): Famous ophthalmologist in Baghdad. Wrote 'Tadhkirat al-Kahhalin' (Notebook of the Oculists), describing 130 specific eye ailments and their pharmacological/surgical remedies.",
