        "id": "bio1_8",
        "sectionNum": "1.8",
        "title": "Levels of Biological Organization",
        "urduTitle": "حیاتیاتی تنظیم کے درجات (Levels of Biological Organization)",
        "content": [
          "Living organisms show hierarchical structural complexity from subatomic particles to the global biosphere:",
          "1. Subatomic and Atomic Level: All matter is composed of subatomic particles (protons, neutrons, electrons) forming atoms of chemical elements. Out of 92 naturally occurring elements, 16 are Bio-elements. Six major bio-elements (Oxygen 65%, Carbon 18%, Hydrogen 10%, Nitrogen 3%, Calcium 2%, Phosphorus 1%) make up 99% of total body mass. Ten trace bio-elements (Potassium, Sulfur, Chlorine, Sodium, Magnesium, Iron, Copper, Manganese, Zinc, Iodine) make up the remaining 1%.",
          "2. Molecular Level: Atoms bond covalently or ionically into biomolecules. Micromolecules have low molecular weights (water, glucose, amino acids); Macromolecules have high molecular weights (starch, glycogen, proteins, DNA).",
          "3. Organelle and Cell Level: Biomolecules assemble into cellular organelles (mitochondria for ATP synthesis, ribosomes for protein synthesis). An organized collection of organelles forms the Cell, the basic structural and functional unit of life.",
          "4. Tissue Level: In multicellular organisms, groups of similar cells specialized to perform a common function form a tissue. Examples: Plant epidermal tissue, xylem, and phloem; Animal epithelial tissue, connective tissue, muscular tissue, and nervous tissue.",
          "5. Organ and Organ System Level: Different tissues working collaboratively form an Organ (e.g., Stomach composed of secretor epithelial tissue and muscular tissue). A collection of organs performing coordinated physiological functions forms an Organ System (e.g., Digestive System comprising mouth, stomach, pancreas, liver, and intestines). Note: Plants exhibit less complex organ systems than animals.",
          "6. Organism Level (Individual): All organ systems work in harmony to constitute an individual organism (e.g., a human running coordinates muscular, respiratory, circulatory, and nervous systems).",
          "7. Population Level: A group of organisms of the same species living together in the same geographical area at the same time (e.g., human population of Pakistan in 2026).",
          "8. Community Level: An assemblage of diverse populations of different species interacting in a common habitat (e.g., a forest community composed of trees, shrubs, birds, fungi, insects, and deer).",
          "9. Biosphere Level (Ecosystem): The global zone of Earth inhabited by living organisms, encompassing atmosphere, lithosphere, and hydrosphere."
        ],
