          "q": "Describe the five-kingdom classification system proposed by Robert Whittaker. Explain the diagnostic features of each kingdom.",
          "ans": "Robert Whittaker (1969) classified all life into Five Kingdoms based on cell type, body complexity, and nutritional mode:\n\n1. Kingdom Prokaryotae (Monera):\n• Cellularity: Unicellular prokaryotes.\n• Nucleus: Lacks membrane-bound nucleus and membrane-bound organelles.\n• Cell Wall: Made of peptidoglycan (murein).\n• Examples: Escherichia coli, Cyanobacteria (Nostoc).\n\n2. Kingdom Protista (Protoctista):\n• Cellularity: Unicellular, simple colonial, or multicellular without tissue differentiation.\n• Nucleus: True eukaryotic nucleus.\n• Nutrition: Photosynthetic autotrophs (algae) or ingestive heterotrophs (protozoans).\n• Examples: Amoeba, Euglena, Paramecium, Kelp.\n\n3. Kingdom Fungi:\n• Cellularity: Multicellular eukaryotic filaments (hyphae), except unicellular yeast.\n• Cell Wall: Chitinous.\n• Nutrition: Absorptive heterotrophs; secrete extracellular enzymes to digest dead organic substrate.\n• Examples: Agaricus (mushroom), Rhizopus (bread mold).\n\n4. Kingdom Plantae:\n• Cellularity: Multicellular eukaryotes with tissue and organ differentiation.\n• Cell Wall: Cellulose.\n• Nutrition: Autotrophic photosynthesis via chlorophyll a & b in chloroplasts.\n• Examples: Ferns, Mosses, Brassica, Sunflower, Mango.\n\n5. Kingdom Animalia:\n• Cellularity: Multicellular eukaryotes lacking cell walls.\n• Nutrition: Ingestive heterotrophs; ingest food and digest it within internal digestive cavities.\n• Motility: Most animals are motile with specialized sensory and nervous systems.\n• Examples: Sponges, Earthworms, Birds, Frog, Humans."
