        "content": [
          "Malaria is an ancient disease known for more than two thousand years. The name 'Malaria' is derived from two Italian words: 'Mala' meaning 'bad' and 'Aria' meaning 'air'. Physicians originally believed bad air from marshes caused the illness.",
          "1. Discovery of Plasmodium (1878):",
          "French army physician Charles Louis Alphonse Laveran examined the blood of a malarial patient under a microscope and observed tiny living microscopic creatures. A few years later, these protozoan parasites were named Plasmodium.",
          "2. Observations of A.F.A. King (1883):",
          "American physician Albert Freeman Africanus King listed twenty crucial observations connecting mosquitoes to malaria, including:",
          "   • People who slept outdoors suffered from malaria much more frequently than those who slept indoors.",
          "   • Individuals who slept under fine mosquito netting rarely contracted malaria.",
          "   • Individuals who slept near smoky fires were protected from malaria.",
          "3. King's Hypothesis & Deduction:",
          "   • Hypothesis: Mosquitoes transmit Plasmodium and are involved in the spread of malaria.",
          "   • Deduction: If mosquitoes transmit Plasmodium, then Plasmodium should be present in mosquitoes that bite malarial patients.",
          "4. Ronald Ross's Experiments (1897):",
          "British army doctor Ronald Ross working in India allowed female Culex mosquitoes to bite sparrows infected with avian malaria. After dissecting the mosquitoes, he found Plasmodium multiplying in the mosquito's stomach wall and migrating to salivary glands. When these infected mosquitoes bit healthy sparrows, the healthy birds contracted malaria!",
          "5. Confirmation in Humans by Giovanni Battista Grassi (1898):",
          "Italian physician Grassi allowed female Anopheles mosquitoes to bite human malarial patients. Later, these mosquitoes bit a healthy human volunteer, who subsequently developed malaria, proving Anopheles is the biological vector for human malaria."
        ],
