        "id": "bio3_4",
        "sectionNum": "3.4",
        "title": "Evolution of Classification Systems: Two to Five Kingdoms",
        "urduTitle": "درجہ بندی کے نظام کا ارتقاء: دو سے پانچ کنگڈم سسٹمز",
        "content": [
          "Classification systems evolved historically as scientific instruments and biochemical knowledge advanced:",
          "1. Two-Kingdom System (Carolus Linnaeus, 1758):",
          "Divided all organisms into Kingdom Plantae (autotrophic, cell-walled, non-motile) and Kingdom Animalia (heterotrophic, lacking walls, motile).",
          "Drawbacks:",
          "• Placed unicellular prokaryotic bacteria and eukaryotic fungi into Plantae despite vast differences.",
          "• Did not distinguish between prokaryotes and eukaryotes.",
          "• Could not accommodate Euglena, which exhibits plant-like photosynthesis in light and animal-like heterotrophy in darkness.",
          "2. Three-Kingdom System (Ernst Haeckel, 1866):",
          "Created Kingdom Protista to accommodate all unicellular microscopic organisms like Euglena, Amoeba, and bacteria, while retaining Plantae and Animalia. However, prokaryotes and eukaryotes remained lumped together in Protista.",
          "3. Four-Kingdom System (Herbert Copeland, 1938):",
          "Separated prokaryotes (bacteria lacking true nuclei) into Kingdom Monera, leaving unicellular eukaryotes in Protista.",
          "4. Five-Kingdom System (Robert Whittaker, 1969; modified by Margulis & Schwartz, 1988):",
          "Based on three criteria: (1) Cellular organization (prokaryotic vs eukaryotic, unicellular vs multicellular); (2) Complexity of body; (3) Mode of nutrition (photosynthesis, absorption, ingestion).",
          "The Five Kingdoms:",
          "• Monera: Prokaryotic unicellular organisms (Bacteria, Cyanobacteria).",
          "• Protista: Eukaryotic unicellular and simple colonial organisms (Amoeba, Euglena, Paramecium, Algae).",
          "• Fungi: Eukaryotic multicellular absorptive heterotrophs with chitin cell walls (Mushrooms, Molds, Yeast).",
          "• Plantae: Eukaryotic multicellular autotrophs with cellulose cell walls (Mosses, Ferns, Flowering plants).",
          "• Animalia: Eukaryotic multicellular ingestive heterotrophs lacking cell walls (Invertebrates, Vertebrates)."
        ],
        "callouts": [
          {
            "type": "scientific",
            "title": "Margulis & Schwartz Modification",
            "content": "In 1988, Lynn Margulis and Karlene Schwartz refined Whittaker's system by incorporating cellular genetics and symbiosis, reclassifying multicellular algae into Kingdom Protoctista."
          }
        ]
