        "title": "Viruses: Borderline Between Living and Non-Living",
        "urduTitle": "وائرس: جاندار اور بے جان کے درمیان کی کڑی",
        "content": [
          "Viruses occupy an anomalous position in biological classification and are excluded from the Five Kingdom system because they are acellular (non-cellular) biological entities:",
          "• Living Characteristics:",
          "  1. They contain genetic material: either DNA or RNA.",
          "  2. They reproduce and multiply rapidly inside living host cells.",
          "  3. They undergo genetic mutations and evolution.",
          "  4. They cause infectious transmissible diseases in plants, animals, and bacteria.",
          "• Non-Living Characteristics:",
          "  1. They lack cellular organization (no cytoplasm, cell membrane, or ribosomes).",
          "  2. They do not carry out independent respiration or metabolism.",
          "  3. Outside living host cells, they are inert chemical particles and can be crystallized like minerals for indefinite storage.",
          "Because of these unique dual properties, viruses are classified as border-line entities between living organisms and non-living chemicals."
        ],
        "callouts": [
          {
            "type": "scientific",
            "title": "Prions and Viroids",
            "content": "Even simpler than viruses are Viroids (infectious naked single-stranded RNA molecules affecting plants) and Prions (infectious misfolded proteins causing Mad Cow disease and Creutzfeldt-Jakob syndrome)."
          }
        ]
