          "Extinction is the complete disappearance of a species from Earth. An Endangered Species is one that is in imminent danger of extinction if the factors causing its decline continue unchecked.",
          "Major Threats to Biodiversity:",
          "1. Habitat Destruction & Fragmentation: Urban expansion, highway construction, industrial zones, and dam construction obliterate natural ecosystems.",
          "2. Deforestation: Indiscriminate clearing of forest cover for agricultural expansion, timber, and fuel leads to soil erosion, rainfall decline, and loss of wildlife canopy.",
          "3. Over-hunting & Poaching: Commercial and illegal hunting of endangered birds and mammals.",
          "4. Pollution: Pesticides, industrial effluents, and plastic waste toxic to terrestrial and aquatic species.",
          "5. Introduction of Invasive Alien Species: Non-native species outcompeting indigenous flora and fauna (e.g., Eucalyptus lowering groundwater tables; Tilapia displacing local fish).",
          "Conservation of Biodiversity in Pakistan:",
          "Pakistan is home to diverse ecosystems from the Arabian Sea mangrove coast to Himalayan peaks. National and international conservation initiatives include:",
