        "content": [
          "The Cell Cycle is the ordered sequence of events that takes place in a cell from its formation through cellular division until it divides into daughter cells.",
          "The cell cycle consists of two major phases: (1) Interphase (90% of cycle duration) and (2) Mitotic Phase (M-Phase, 10% of cycle duration).",
          "Interphase (Phase of High Metabolic Activity):",
          "Historically called the 'resting phase', interphase is actually the most biochemically active phase where the cell grows, synthesizes biomolecules, and duplicates its genome. Interphase is divided into three successive sub-phases:",
          "1. G1 Phase (First Gap Phase):",
          "• Intense protein synthesis and manufacturing of structural organelle enzymes.",
          "• Cell size increases substantially.",
          "• Mitochondria and ribosomes multiply.",
          "2. S Phase (Synthesis Phase):",
          "• DNA replication occurs: the cell duplicates its entire chromosomal DNA.",
          "• Chromosomes transition from single chromatids to duplicated chromosomes composed of two sister chromatids joined at the centromere.",
          "3. G2 Phase (Second Gap Phase):",
          "• Synthesis of specific proteins required for cell division, particularly tubulin proteins for the assembly of the mitotic spindle apparatus.",
          "• The cell undergoes final quality-control checks before initiating mitosis.",
          "4. G0 Phase (Quiescent State):",
          "• In mature multicellular organisms, some cells temporarily or permanently exit the cell cycle and cease dividing (e.g., mature neurons and skeletal muscle cells remain in G0 permanently; liver cells enter G0 semi-permanently and only divide upon tissue injury)."
        ],
