            "title": "Cell Cycle Checkpoints",
            "content": "Molecular surveillance checkpoints (G1 checkpoint, G2 checkpoint, M checkpoint) inspect DNA integrity before permitting the cell to advance to the next phase, preventing cancerous mutations."
