          "• Sequence: Cell shrinks, chromatin condenses, nuclear DNA fragments, and cell blebs into membrane-bound apoptotic bodies that are quietly phagocytosed by macrophages without causing inflammation.",
          "• Biological Roles: (a) Sculpting digits (fingers and toes) during human embryonic limb development by removing interdigital webbing; (b) Eliminating damaged cells carrying cancerous mutations; (c) Tail resorption during frog metamorphosis.",
