          "q": "Compare Mitosis and Meiosis across ten diagnostic criteria including site, divisions, daughter cells, ploidy, crossing over, and genetic variation.",
          "ans": "Comparative Analysis:\n\n1. Occurrence: Mitosis occurs in somatic cells; Meiosis occurs in germ-line cells (gonads).\n2. Number of Divisions: Mitosis has 1 nuclear division; Meiosis has 2 nuclear divisions (Meiosis-I and Meiosis-II).\n3. Number of Daughter Cells: Mitosis produces 2 daughter cells; Meiosis produces 4 daughter cells.\n4. Chromosome Number (Ploidy): Mitosis maintains diploid status (2n ➔ 2n); Meiosis halves chromosome number (2n ➔ 1n).\n5. Synapsis of Homologues: Completely absent in Mitosis; occurs in Prophase-I of Meiosis.\n6. Crossing Over: Does not occur in Mitosis; occurs between non-sister chromatids in Meiosis-I.\n7. Metaphase Alignment: In Mitosis, individual chromosomes align in a single line; in Meiosis-I, homologous pairs align in two rows.\n8. Anaphase Separation: In Mitotic Anaphase, sister chromatids separate; in Meiosis-I Anaphase, homologous chromosomes separate (centromeres stay intact).\n9. Genetic Identity: Mitosis produces genetically identical clones; Meiosis produces genetically diverse recombinants.\n10. Biological Function: Mitosis powers body growth, tissue repair, and asexual reproduction; Meiosis produces gametes for sexual reproduction."
