          "q": "Describe in detail the factors that affect the rate of enzyme action: Temperature, pH, and Substrate Concentration. Illustrate with graph descriptions.",
          "ans": "Enzymatic velocity is regulated by three main factors:\n\n1. Effect of Temperature:\n• As temperature rises from 0°C toward optimum, kinetic energy increases, raising enzyme-substrate collisions and accelerating the reaction rate.\n• Optimum Temperature: Peak catalytic velocity (37°C for human enzymes).\n• Beyond Optimum (Above 40°C): Extreme heat causes high-frequency thermal vibrations that disrupt non-covalent bonds (hydrogen and ionic bonds) stabilizing the protein's tertiary structure. The active site deforms—this is Denaturation. Denaturation is irreversible, causing reaction velocity to plunge to zero.\n\n2. Effect of pH:\n• Every enzyme has an Optimum pH. Pepsin operates at pH 1.5–2.0 (gastric acid), salivary amylase at pH 6.8, and trypsin at pH 7.8–8.0 (alkaline bile).\n• Deviation from optimum pH alters the electric charges on acidic and basic amino acid side chains within the active site. This impairs substrate binding. Extreme pH shifts cause complete irreversible protein denaturation.\n\n3. Effect of Substrate Concentration:\n• At low substrate concentrations, increasing substrate directly increases reaction rate because unoccupied active sites become engaged.\n• Saturation Point: As substrate concentration increases further, a point is reached where ALL enzyme active sites are continuously engaged in catalysis. The reaction reaches maximum velocity (Vmax). Adding further substrate has zero effect on rate because the enzyme concentration is now the limiting factor."
