        "content": [
          "In previous units, you learned that living organisms perform diverse vital activities: cell division, movement, biosynthesis, growth, active transport, and nerve transmission. All these vital processes require energy.",
          "Bioenergetics is the study of the capture, transformation, storage, and utilization of energy in living organisms.",
          "7.1.1 Oxidation-Reduction (Redox) Reactions:",
          "• Energy in biological systems is stored in chemical covalent bonds of organic molecules (glucose, lipids).",
          "• Oxidation: The loss of electrons, loss of hydrogen atoms, or gain of oxygen.",
          "• Reduction: The gain of electrons, gain of hydrogen atoms, or loss of oxygen.",
          "• Redox Reactions: In living cells, oxidation and reduction always occur simultaneously. When food molecules are oxidized (broken down), electrons with associated hydrogen protons are extracted and transferred via coenzymes (NAD+, FAD) to lower energy levels, releasing energy used to synthesize ATP.",
          "7.1.2 ATP: The Universal Energy Currency of the Cell:",
          "• Adenosine Triphosphate (ATP) was discovered by Karl Lohmann in 1929 and identified as the primary cellular energy currency by Fritz Lipmann in 1941.",
          "• Structure of ATP: Consists of three molecular subunits:",
          "  1. Adenine: A double-ring nitrogenous base.",
          "  2. Ribose: A five-carbon pentose sugar.",
          "  3. Three Phosphate Groups (PO4^3-): Linked in a linear chain by covalent bonds.",
          "• High-Energy Phosphate Bonds: The two terminal phosphate-phosphate bonds (represented by a wavy line '~') are high-energy bonds because negative electrical charges on adjacent phosphate groups strongly repel each other.",
          "• Energy Yield: Hydrolysis of the terminal phosphate bond converts ATP to ADP (Adenosine Diphosphate) and inorganic phosphate (Pi), releasing 7.3 kcal/mole (approximately 31.8 kJ/mole):",
          "  ATP + H2O ⇌ ADP + Pi + 7.3 kcal/mol (31.8 kJ/mol)",
          "• When required, ADP can be further hydrolyzed into AMP (Adenosine Monophosphate), releasing an additional 7.3 kcal/mole."
        ],
