        "content": [
          "Cellular Respiration is the intracellular catabolic process in which organic food molecules (especially glucose) are systematically oxidized to release chemical energy that is captured in the form of ATP.",
          "7.4.1 Types of Respiration:",
          "1. Aerobic Respiration (Requires Molecular Oxygen):",
          "• Complete oxidation of glucose into carbon dioxide and water in the presence of O2 with high energy yield (36 or 38 ATP per glucose).",
          "• Equation: C6H12O6 + 6O2 ➔ 6CO2 + 6H2O + 36 ATP (Energy)",
          "2. Anaerobic Respiration (Fermentation - Occurs Without Oxygen):",
          "• Incomplete breakdown of glucose in the absence of O2 with low energy yield (only 2 net ATP per glucose).",
          "• Two Common Fermentation Types:",
          "  a) Lactic Acid Fermentation: Glucose is cleaved into two molecules of Lactic Acid (C3H6O3). Occurs in lactic acid bacteria (sour milk/yogurt) and in human skeletal muscle cells during vigorous sprinting when oxygen supply cannot meet muscle demands, causing temporary muscle fatigue.",
          "     C6H12O6 ➔ 2 Lactic Acid + 2 ATP",
          "  b) Alcoholic Fermentation: Glucose is broken down into Ethyl Alcohol (Ethanol, C2H5OH) and Carbon Dioxide gas. Occurs in yeast (Saccharomyces cerevisiae) and some bacteria, utilized in baking and brewing.",
          "     C6H12O6 ➔ 2 Ethanol + 2 CO2 + 2 ATP",
          "7.4.2 The Three Sequential Stages of Aerobic Respiration:",
          "1. Glycolysis (Cytoplasm):",
          "• Occurs in the cytoplasm of all living cells; does not require oxygen.",
          "• A 6-carbon glucose molecule is cleaved into two 3-carbon Pyruvic Acid (pyruvate) molecules.",
          "• Net Yield: 2 ATP (via substrate-level phosphorylation) and 2 NADH.",
          "2. Krebs Cycle / Citric Acid Cycle (Mitochondrial Matrix):",
          "• Pyruvate enters the mitochondrion, is oxidized to 2-carbon Acetyl-CoA (releasing 2 CO2 and 2 NADH), and enters the cyclical Krebs pathway discovered by Sir Hans Krebs.",
          "• Yield per glucose (two turns): 2 ATP, 6 NADH, 2 FADH2, and 4 CO2.",
          "3. Electron Transport Chain / Oxidative Phosphorylation (Mitochondrial Cristae):",
          "• High-energy electrons from NADH and FADH2 pass down a series of electron carriers (cytochromes).",
          "• The released energy pumps protons across the inner mitochondrial membrane, driving ATP synthesis via ATP Synthase.",
          "• Oxygen serves as the final electron acceptor, combining with protons to form Water (H2O).",
          "• Each NADH yields 3 ATP; each FADH2 yields 2 ATP."
        ],
