    "keyPoints": [
      "Plants require macronutrients (Nitrogen, Magnesium) and micronutrients (Iron, Zinc) for growth.",
      "Nitrogen deficiency causes chlorosis and stunted growth; magnesium deficiency impairs chlorophyll synthesis.",
      "Organic fertilizers improve soil texture; chemical fertilizers provide targeted nutrients but risk water eutrophication.",
      "The six major nutrient classes are carbohydrates, lipids, proteins, vitamins, minerals, and water.",
      "Carbohydrates provide 4 kcal/g, proteins 4 kcal/g, and lipids 9 kcal/g.",
      "Vitamin A deficiency causes night blindness; Vitamin C causes scurvy; Vitamin D causes rickets.",
      "Calcium is required for bones and blood clotting; Iron is the central cofactor in hemoglobin (deficiency causes anemia).",
      "Protein-energy malnutrition causes Kwashiorkor (protein deficiency with edema) and Marasmus (total starvation wasting).",
      "The human alimentary canal includes oral cavity, pharynx, esophagus, stomach, small intestine, and large intestine.",
      "Salivary amylase digests starch; stomach pepsin digests proteins in acidic HCl (pH 2).",
      "The liver produces bile to emulsify fats; the pancreas secretes trypsin, lipase, and amylase into the duodenum.",
      "Finger-like villi and microvilli in the ileum maximize surface area for nutrient absorption into blood capillaries and lacteals.",
      "Common gut disorders include diarrhea (dehydration treated with ORS), constipation (prevented by dietary fiber), and peptic ulcers (caused by H. pylori)."
    ],
