          "q": "Describe the physiological role of the Liver in carbohydrate, protein, and lipid metabolism. Explain how the liver maintains homeostatic blood glucose levels.",
          "cognitiveLevel": "Understanding",
          "ans": "The Liver is the master homeostatic metabolic organ:\n\n1. Carbohydrate Metabolism & Glucose Homeostasis:\n• Postprandial State (After Meals): High glucose in the hepatic portal vein triggers the pancreatic hormone Insulin. The liver absorbs glucose and polymerizes it into Glycogen for storage (Glycogenesis).\n• Fasting State (Between Meals): When blood glucose drops below 90 mg/dL, the pancreatic hormone Glucagon triggers the liver to hydrolyze glycogen into free glucose (Glycogenolysis), releasing it into the blood.\n• Prolonged Starvation: The liver synthesizes glucose de novo from non-carbohydrate sources like glycerol and amino acids (Gluconeogenesis).\n\n2. Protein Metabolism:\n• Deamination: Excess amino acids cannot be stored. Hepatocytes remove the amino group (-NH2), converting toxic ammonia into water-soluble Urea via the urea cycle for renal excretion.\n• Plasma Protein Synthesis: Synthesizes almost all circulating blood proteins: Albumin (osmotic regulator), Fibrinogen, and Prothrombin (clotting factors).\n\n3. Lipid Metabolism:\n• Bile Synthesis: Synthesizes bile acids and salts from cholesterol to emulsify fats in the duodenum.\n• Lipoprotein Synthesis: Packages endogenous lipids into VLDL and HDL for transport across the vascular system.\n• Beta-Oxidation: Breaks down fatty acids into acetyl-CoA and ketone bodies for energy during carbohydrate scarcity."
