          "q": "Explain the causes, biochemical and physiological symptoms, and preventive measures for Protein-Energy Malnutrition (PEM), contrasting Marasmus and Kwashiorkor.",
          "cognitiveLevel": "Application",
          "ans": "Protein-Energy Malnutrition (PEM) is the leading cause of infant mortality in developing nations:\n\n1. Kwashiorkor:\n• Primary Cause: Severe dietary protein deficiency in the presence of adequate or marginal carbohydrate calories. Typically occurs in children aged 1–4 years when abruptly weaned onto low-protein starch gruels.\n• Pathophysiology & Symptoms:\n  - Hypoalbuminemia: Lack of amino acids prevents liver synthesis of plasma albumin. Lowered intravascular oncotic pressure causes fluid to leak into interstitial spaces, producing severe Edema (swollen, bloated abdomen and legs).\n  - Hepatomegaly: Decreased apolipoprotein synthesis traps triglycerides inside liver cells, causing enlarged fatty liver.\n  - Dermatosis: Flaking, dark peeling skin ('flaky paint' dermatosis) and dry, reddish-copper brittle hair.\n  - Child appears lethargic, irritable, and apathetic.\n\n2. Marasmus:\n• Primary Cause: Severe total calorie and protein starvation ('dry' starvation) affecting infants under 1 year due to early cessation of breastfeeding or diluted contaminated formula.\n• Pathophysiology & Symptoms:\n  - Extreme catabolism: Body mobilizes all subcutaneous fat reserves and catabolizes skeletal muscle mass for basal survival.\n  - Physical Appearance: Shrunken, emaciated body with prominent rib cage, sunken eyes, loose folded skin, and a wrinkled elderly 'monkey-like' face.\n  - Absence of edema: Plasma albumin remains sufficient to prevent fluid extravasation.\n  - Child suffers extreme hunger, persistent crying, severe hypothermia, and hypoglycemia.\n\nPrevention and Public Health Management:\n• Promoting exclusive maternal breastfeeding for the first six months of life.\n• Introducing protein-dense complementary weaning foods (eggs, milk, lentils, fortified peanut paste like RUTF - Ready-to-Use Therapeutic Food).\n• Providing national nutrition education, clean water supplies, and maternal food supplements."
