        "urduTitle": "پانی کا اوپر چڑھنا (Ascent of Sap) اور خوراک کی ترسیل",
        "content": [
          "Ascent of Sap is the upward conduction of water and dissolved minerals from root hairs through xylem vessels to the tops of towering trees (reaching over 100 meters in redwoods).",
          "Mechanism: Dixon and Joly's Cohesion-Tension Theory (1894):",
          "1. Transpiration Pull: Evaporation of water from leaf mesophyll cells creates negative suction tension (low water potential) in leaf xylem.",
          "2. Cohesion: Attractive hydrogen bonding between adjacent water molecules creates an unbroken, continuous, rope-like water column inside xylem vessels.",
          "3. Adhesion: Attractive physical forces between water molecules and the hydrophilic cellulose/lignin walls of xylem vessels prevent the water column from breaking.",
          "The upward transpirational pull sucks the cohesive water column upward through the stem without requiring metabolic energy.",
          "Translocation of Food in Phloem (Ernst Münch's Pressure-Flow Theory, 1930):",
          "• Translocation is the transport of soluble organic food (primarily sucrose) from Source (photosynthetic mature leaves or storage roots) to Sink (growing roots, developing flowers, buds, fruits).",
          "• Mechanism:",
          "  1. Loading at Source: Companion cells actively pump sucrose into sieve tube elements, lowering water potential inside phloem.",
          "  2. Osmotic Influx: Water enters sieve tubes from adjacent xylem by osmosis, generating high Hydrostatic Turgor Pressure.",
          "  3. Bulk Flow: High hydrostatic pressure at the source forces the sugar sap to flow en masse through sieve plates toward low-pressure sinks.",
          "  4. Unloading at Sink: Sucrose is actively unloaded at the sink and converted into insoluble starch, water exits phloem back to xylem, and hydrostatic pressure drops."
        ],
