          "Blood circulates through three types of blood vessels: Arteries, Capillaries, and Veins:",
          "1. Arteries: Thick, muscular, highly elastic walls composed of three layers (tunica externa, media, intima) with narrow lumen; carry blood away from the heart under high pulsatile pressure; carry oxygenated blood (except Pulmonary Artery).",
          "2. Capillaries: Microscopic, single-cell-thick vessels composed solely of a single layer of squamous endothelium; site of all metabolic exchange of gases, nutrients, and wastes between blood and tissue fluid via diffusion.",
          "3. Veins: Thin-walled, less muscular vessels with wide lumen and internal semilunar valves that prevent backward pooling of blood; carry blood toward the heart under low pressure; carry deoxygenated blood (except Pulmonary Veins).",
          "Cardiovascular Disorders (Leading Cause of Global Mortality):",
          "1. Atherosclerosis: Narrowing and hardening of arterial lumen caused by the accumulation of fatty cholesterol deposits (Atheromatous Plaques) inside the tunica intima, triggering chronic inflammation and thrombosis.",
          "2. Arteriosclerosis: Generalized degenerative loss of elasticity and calcification of arterial walls ('hardening of arteries') with aging, leading to chronic hypertension.",
          "3. Angina Pectoris: Severe, suffocating chest pain radiating down the left shoulder and arm caused by temporary myocardial ischemia (insufficient oxygenated blood supply through narrowed coronary arteries during exertion).",
          "4. Myocardial Infarction (Heart Attack): Complete acute occlusion of a coronary artery by an atheroma or blood clot (thrombus), causing ischemic necrosis (death) of that portion of the heart muscle.",
          "• Symptoms: Crushing central retrosternal chest pain, sweating, shortness of breath, nausea.",
          "• Treatments: Emergency clot-dissolving drugs (streptokinase), Angioplasty with stent placement, and Coronary Artery Bypass Graft (CABG) surgery."
