          "q": "Explain why Curtis described Transpiration as a 'Necessary Evil'.",
          "ans": "Curtis termed transpiration a 'necessary evil' because:\n• Necessary: It creates the Transpiration Pull that pulls water and minerals up tall trees, provides evaporative cooling to protect leaves from solar heat, and facilitates mineral transport.\n• Evil: Evaporative water loss is massive (plants lose over 90% of absorbed water). In dry soil, excessive transpiration causes severe wilting, desiccation, and plant death."
